) AS v(machine_class, location, machine_name, machine_description, currency_code, country_code, source_type, process_group, operators, setup_time_hr, landed_machine_cost, direct_overhead_rate, indirect_overhead_rate, benchmark_direct_overhead_rate_usd_hr, benchmark_indirect_overhead_rate_usd_hr, total_machine_hour_rate, mhr_usd_per_hour, usd_labor_rate_per_hr, benchmark_labor_rate_usd_hr, usd_lhr_total, work_center_labor_rate_factor, labor_time_standard, wage_grade, machine_price_usd, machine_length_mm, machine_width_mm, footprint_allowance_factor, machine_power_kw, machine_life_yr, installation_factor_pct, machine_uptime_pct, annual_maintenance_factor_pct, salvage_value_factor_pct, supplies_cost_per_year, avg_utilization, good_part_yield, manufacturer_country, max_x_mm, max_y_mm, max_z_mm, max_workpiece_weight_kg, capability_source, specs, benchmark_source_key)
